sys_ux_client_script.script:
/**
* @param {Object} params
* @param {Object} params.api
* @param {Object} params.helpers
* @returns {string} A comma-separated list of short descriptions containing the keyword.
*/
function evaluateProperty({ api, helpers }) {
    const kpi = api.data.sam_foundation_current_kpis_1.output.users_kpi;

    const output = kpi.map(record => {
    // Split the usecase string into words and take the first three
    return record.usecase.split(/\s+/).slice(0, 3).join(' ');
});

    console.log(output);
    if (output.length > 0) {
    // Map the array to create the query string
    const query = output.map(value => `descriptionSTARTSWITH${value}`).join('^OR');

    // Log the resulting query
    console.log(query); // Output: "descriptionSTARTSWITHhii a b^ORdescriptionSTARTSWITHhiig fgh gh"
    return query;
}


    return "descriptionSTARTSWITHUser with missing^ORdescriptionSTARTSWITHTracking financial";




}
